import csv,pathlib
p=pathlib.Path(__file__).parent
def save(file,headers,rows):
 with open(p/file,'w') as f:
  w=csv.writer(f);w.writerow(headers);w.writerows(rows)
k=[
('Source selection','For a question within one airline subject, prefer its ZAL_VW enriched view, which already contains descriptive dimensions. Base ZAL_FACT and corresponding ZAL_VW represent the same subject; never union or add their totals.'),
('Fact grain safety','Flight, cabin load, ticket segment, ancillary sale, survey response, service case, baggage claim, maintenance event, crew assignment, customer-month, product-month, and route-month are distinct grains. Aggregate each subject to common comparison keys before combining; do not join independent detail facts and sum measures.'),
('Route profitability','Use ZAL_VW_ROUTE_PNL_MONTHLY for route revenue, full operating cost, operating income, and budget comparisons. Flight direct cost excludes some route P&L cost categories and is not full operating profitability.'),
('Travel versus booking period','Use flight_date for travel or flown ticket analysis. Use booking_date only for booking-period questions. Ancillary purchase_date, survey_date, service opened_date, baggage report_date, and maintenance start_date each describe different events; state the chosen basis.'),
('Reporting clock','The existing Airline Command Cockpit states coverage from 2024-10-01 through 2026-09-30 and uses September 2026 as its comparable opening period. Verify actual source coverage before answering latest-period questions. Never silently use the wall-clock current month when no data exists for it.'),
('Historical loyalty tier','Use tier_at_month_end from the monthly loyalty fact for historical loyalty segmentation. loyalty_tier from the customer dimension is a customer attribute and must not be represented as historical monthly tier.'),
('Snapshot measures','miles_balance_end and status_dollars_ytd are snapshots or cumulative balances. Aggregate across customers at a chosen month, not across months. Monthly active_accounts and account status counts are not unique annual accounts.'),
('Ratios and missing denominators','Calculate portfolio ratios from aggregated numerators and denominators, never an unweighted average of subgroup percentages. Return null or explain undefined when denominator is zero. Do not replace unknown values with zero without an explicit rule.'),
('NPS definition','NPS is 100 times promoter count minus detractor count divided by valid response count. Valid nps_score is between 0 and 10; promoters score 9 or 10, detractors 0 through 6, and passives 7 or 8. The mean recommendation score is not NPS.'),
('Arrival punctuality','For ordinary on-time arrival performance, exclude cancelled and diverted flights from numerator and denominator. Use the recorded arrival_on_time_flag on eligible flights. Report cancellations and diversions separately.'),
('Revenue semantics','Ticket total_fare includes recorded fare components and is not automatically recognized passenger revenue. Route P&L passenger revenue, ticket passenger revenue, and ancillary transaction net_amount have different grains and may have different accounting bases; do not assume reconciliation without testing.'),
('Capacity and traffic','Passenger-count load factor is passengers_boarded divided by seats_available. Distance-weighted traffic load factor is revenue_passenger_miles divided by available_seat_miles. Name which definition is used; these are different measures.'),
('Survey and case populations','Survey responses, service cases, and baggage claims are event records, not a census of passengers. Report their sample sizes. Counts of cases or claims must not be called unique affected passengers without distinct customer or ticket counting.'),
('Co-brand economics','Partner remuneration records miles-sale remuneration, acquisition bounty, brand licensing, total remuneration, and program cost. Cardholder spend is not airline revenue. Do not add card spend to route revenue.'),
('Unsupported commercial claims','No named corporate account dimension or contract commitment table is present in this schema. corporate_account_flag supports flagged-customer segmentation but does not establish named-account contract attainment or wallet share.'),
('Causality and scenarios','Observed associations do not establish causal impacts. The LiveApp scenario planner is a deterministic route calculator, not a demand forecast, optimizer, elasticity estimate, schedule feasibility model, propensity model, or retention-effect model.'),
('Money and units','Preserve source monetary units. The schema alone does not establish currency or foreign-exchange conversion. Do not label amounts EUR or USD unless source documentation confirms currency. Miles are distance or loyalty units according to the column context.'),
('Timezones','Source timestamp timezone semantics are unverified. Do not assume all airports share one timezone or calculate cross-airport elapsed time from local timestamps without confirmation. Prefer recorded block-minute measures.'),
('Weather attribution','Weather severity, deicing, and ground stops describe airport-day conditions. Match weather to the correct airport role and date; do not join both origin and destination weather as interchangeable rows or claim causal attribution from correlation.'),
('PII and presentation','Use aggregated workshop examples by default. Technical keys are identifiers, not additive measures. Avoid unnecessary display of member numbers, employee identifiers, or individual credit-related attributes in executive summaries.'),
('Synthetic workshop extensions','Tables prefixed WORKSHOP_SYNTHETIC are invented teaching data. Keep them separate from source airline actuals. Do not use synthetic narratives or targets as evidence of real operational events or published business targets.'),
('Calendar assumptions','Source date dimensions provide calendar_year and quarter_num. Use those calendar fields; no custom fiscal-year convention has been established. State period boundaries explicitly for comparisons.')]
k.append(('Customer segment analysis', 'There is no single canonical customer segment or mandatory drill-down hierarchy in this dataset. Ask which dimension is intended when the request is ambiguous. Available customer attributes include traveler_type, loyalty_tier, age_band, card_holder_type and corporate_account_flag; route market_segment is a route attribute, not a customer segment. For ticket passenger-revenue analysis, use SUM(passenger_revenue) from ZAL_VW_TICKET_SEGMENT and explicitly state flight_date versus booking_date. Do not substitute total_fare or allocate route P&L revenue to customers. Describe customer attributes as recorded rather than historically effective unless temporal history has been verified. Agree the dimension and period before ranking; drill down to another stated attribute only when requested.'))
save('context/knowledge.csv',['Knowledge'],[[name+': '+description] for name,description in k])
syn=[('On-time arrival','arrival punctuality, on-time arrival performance, arrival OTP'),('Net Promoter Score','NPS, net promoter score'),('Available seat miles','ASM, available seat miles'),('Revenue passenger miles','RPM, revenue passenger miles'),('Passenger revenue per available seat mile','PRASM, passenger RASM'),('Total revenue per available seat mile','RASM, TRASM, total RASM'),('Cost per available seat mile','CASM, operating cost per ASM'),('Operating income','operating profit, route operating income'),('Co-brand','cobrand, co-branded, co branded'),('Ancillary','add-on, ancillary product, optional extra'),('Origin airport','departure airport, origin station'),('Destination airport','arrival airport, destination station'),('Premium cabin','premium cabin, premium seating'),('Year over year','YoY, year-on-year, prior year comparison'),('Month over month','MoM, prior month comparison'),('Aircraft registration','tail number, aircraft tail'),('First contact resolution','FCR, first-contact resolution'),('Customer satisfaction','CSAT, customer satisfaction score'),('Route profit and loss','route P&L, route PNL, route financials'),('Travel month','flown month, flight month'),('Booking month','booked month, reservation month'),('Baggage claim','bag claim, baggage incident'),('Maintenance downtime','aircraft downtime, maintenance out-of-service hours')]
save('context/synonyms.csv',['Name','Synonyms'],syn)
metrics=[]
def metric(name,t,expr,desc):
 full='wisdomai.'+t
 # imported expression uses table-qualified fields, matching existing export format
 import re
 cols=set(r['Column Name'] for r in csv.DictReader(open(p/'evidence/metadata-before.csv')) if r['Table Name']==t and r['Column Name'])
 expanded=re.sub(r'\b[a-z][a-z_0-9]*\b',lambda m:full+'.'+m.group() if m.group() in cols else m.group(),expr)
 metrics.append([name,desc,expanded,'wisdomai','SQL','TABLE','Ali-TD',full,expanded,expanded,'DISPLAY_FORMAT_UNKNOWN',2,'true',''])
t='ZAL_VW_ROUTE_PNL_MONTHLY'
for n,c in [('Route Total Revenue','total_revenue'),('Route Passenger Revenue','passenger_revenue'),('Route Ancillary Revenue','ancillary_revenue'),('Route Operating Cost','total_operating_cost'),('Route Operating Income','operating_income'),('Route Budget Revenue','budget_revenue'),('Route Budget Operating Income','budget_operating_income')]:metric(n,t,f'SUM({c})','Sum at route-month grain; preserve source money units.')
for n,e,d in [('Passenger Count Load Factor %','100.0 * SUM(passengers_boarded) / NULLIF(SUM(seats_available),0)','Boarded passengers / available seats; ratio of sums; 0–100.'),('Distance Weighted Load Factor %','100.0 * SUM(revenue_passenger_miles) / NULLIF(SUM(available_seat_miles),0)','RPM / ASM; 0–100; distinct from passenger-count load factor.'),('Operating Margin %','100.0 * SUM(operating_income) / NULLIF(SUM(total_revenue),0)','Operating income / total revenue; 0–100 percentage scale.'),('RASM','SUM(total_revenue) / NULLIF(SUM(available_seat_miles),0)','Source money units per available seat mile; not cents unless explicitly converted.'),('PRASM','SUM(passenger_revenue) / NULLIF(SUM(available_seat_miles),0)','Passenger revenue per ASM in source money units.'),('CASM','SUM(total_operating_cost) / NULLIF(SUM(available_seat_miles),0)','Full operating cost per ASM in source money units.'),('Passenger Yield','SUM(passenger_revenue) / NULLIF(SUM(revenue_passenger_miles),0)','Passenger revenue per RPM in source money units.'),('Revenue Versus Budget','SUM(total_revenue) - SUM(budget_revenue)','Actual less budget revenue; positive is above budget.'),('Income Versus Budget','SUM(operating_income) - SUM(budget_operating_income)','Actual less budget operating income.')]:metric(n,t,e,d)
metric('Survey NPS','ZAL_VW_PASSENGER_SURVEY','100.0 * SUM(CASE WHEN nps_score BETWEEN 9 AND 10 THEN 1 WHEN nps_score BETWEEN 0 AND 6 THEN -1 ELSE 0 END) / NULLIF(SUM(CASE WHEN nps_score BETWEEN 0 AND 10 THEN 1 ELSE 0 END),0)','NPS from valid 0–10 responses; range -100 to 100.')
metric('Arrival On Time %','ZAL_VW_FLIGHT','100.0 * SUM(CASE WHEN cancelled_flag = 0 AND diverted_flag = 0 AND arrival_on_time_flag = 1 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN cancelled_flag = 0 AND diverted_flag = 0 THEN 1 ELSE 0 END),0)','Eligible arrivals exclude cancelled and diverted flights; confirm flag encoding in validation.')
metric('Cancellation Rate %','ZAL_VW_FLIGHT','100.0 * SUM(CASE WHEN cancelled_flag = 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(*),0)','Cancelled scheduled flight legs divided by all scheduled flight legs.')
metric('Ancillary Net Revenue','ZAL_VW_ANCILLARY_SALE','SUM(net_amount)','Net ancillary transaction amount; purchase-period basis unless explicitly filtered by travel date.')
metric('Ancillary Contribution','ZAL_VW_ANCILLARY_SALE','SUM(net_amount) - SUM(cost_amount)','Net amount less recorded ancillary cost; not full airline operating profit.')
metric('Co-brand Net Remuneration','ZAL_VW_PARTNER_REMUNERATION_MONTHLY','SUM(total_remuneration) - SUM(program_cost)','Partner remuneration less recorded program cost at product-month grain.')
metric('Service Case Cash Compensation','ZAL_VW_SERVICE_CASE','SUM(compensation_cash)','Cash compensation only; do not add compensation_miles without an agreed valuation.')
save('context/metrics.csv',['Name','Description','SQL','Database','Type','Scope','Connection','Tables','Expression','Expanded SQL','Display Format','Precision','Included','Stale Reason'],metrics)
print('Knowledge',len(k),'Synonyms',len(syn),'Metrics',len(metrics))
